// Transcript rows (turnStatusRows): the 3.6556.2 status rows generated by scripts/extract-transcript-rows.mjs, mounted
// by src/source-transcript-rows.jsx under the transcript root's scope. SSR in middleware mode only (hmr / ws off).
import test, { before, after } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import React from 'react';
import { renderToStaticMarkup } from 'react-dom/server';
import { createServer } from 'vite';
import react from '@vitejs/plugin-react';
import { extractTranscriptRows } from '../scripts/extract-transcript-rows.mjs';

const app = path.resolve(import.meta.dirname, '..');
const dir = path.join(app, 'src/generated/transcript-rows');
const manifest = JSON.parse(fs.readFileSync(path.join(dir, 'manifest.json'), 'utf8'));
let server, Rows, Session, Group, Model, Growth;
before(async () => {
  server = await createServer({ configFile: false, root: app, plugins: [react()], server: { middlewareMode: true, hmr: false, ws: false, watch: null },
    appType: 'custom', logLevel: 'error' });
  Rows = await server.ssrLoadModule('/src/source-transcript-rows.jsx');
  Session = await server.ssrLoadModule('/src/source-session.jsx');
  Group = await server.ssrLoadModule('/src/source-tool-group.jsx');
  Model = await server.ssrLoadModule('/src/transcript-rows-model.mjs');
  Growth = await server.ssrLoadModule('/src/host-growthbook.mjs');
});
after(() => server?.close());
const h = React.createElement;
const inScope = (child, scope = {}) => renderToStaticMarkup(h(Rows.TranscriptRowsScope, { sessionKey: 'code:s', ...scope }, child));

test('generator --check, linked to the working line (one TurnStatus, one gate, one mark)', async () => {
  await extractTranscriptRows({ check: true });
  // 2026-10-18: the session rail is linked too (shared-25 $U/YU, shared-78 YD/sN, shared-130 Y were sliced in both areas).
  // 2026-10-18 (tool results): r3b-transcript's session file contexts and files-changes' gone check / session id context
  // are linked module by module (the file link reads the same contexts as the Turn edits card and the Files pane).
  // 2026-10-26: files-changes is on 3.6556.2 (w2-files) without a 2.42304.0 segment, so its two modules link through the
  // frozen 2.42304.0 view this area holds (E34): the old locals are served by the current modules' semantic exports.
  // 2026-10-26 (w6-transcript-rows): r3b-transcript's step 2 (the Turn edits card and its session file access) is on
  // 3.6556.2 too, linked the same way.
  // 2026-10-26 (w6-transcript-rows-cont): this area is on 3.6556.2 too, so both link the current modules directly (the
  // frozen 2.42304.0 views are gone).
  assert.equal(manifest.referenceVersion, '3.6556.2');
  // w10-cleanup-slicer-d1 (D1): code-current's file-output-paths.mjs is linked too (it slices shared-130 WV / zH; the
  // manifest lists its bindings without an export table, so runSlicer reads the file's own exports).
  assert.deepEqual(manifest.linkedAreas, ['working-line', 'session-rail', { area: 'r3b-transcript', modules: ['session-file-access.mjs'] },
    { area: 'files-changes', modules: ['file-gone-check.mjs', 'session-context.mjs'] }, { area: 'code-current', modules: ['file-output-paths.mjs'] },
    // w13-close-gen-dedup (w12-carry-01, D1): shared-156's display-safety helpers are code-routines' one copy.
    { area: 'code-routines', modules: ['shared-156-BLTosN8U.mjs'] }, { area: 'session-rail-kit', modules: ['plain-object.mjs'] },
    // w13-close-gen-dedup review 1 (D1): shared-0's Pa / jL / ML / Vy … hb and the rest routines-shared slices are its one copy.
    { area: 'routines-shared', modules: ['shared-0-DDOOdL6P.mjs'] }]);
  const rows0 = fs.readFileSync(path.join(app, 'src/generated/transcript-rows/rows-shared-0-DDOOdL6P.mjs'), 'utf8');
  assert.doesNotMatch(rows0, /^function (sW|Pa|Vy|Hy|Ky|fb|hb|SA)\(/m);
  assert.doesNotMatch(rows0, /^var (jL|ML|AL|bA) =/m);
  assert.doesNotMatch(fs.readFileSync(path.join(app, 'src/generated/transcript-rows/rows-shared-156-BLTosN8U.mjs'), 'utf8'), /^function (VX|qX|RX)\(/m);
  for (const area of ['working-line', 'session-rail', 'r3b-transcript', 'files-changes'])
    assert.equal(JSON.parse(fs.readFileSync(path.join(app, 'src/generated', area, 'manifest.json'), 'utf8')).referenceVersion, '3.6556.2', area);
  const linkedFiles = fs.readdirSync(dir).filter(f => f.endsWith('.mjs')).map(f => fs.readFileSync(path.join(dir, f), 'utf8')).join('\n');
  assert.match(linkedFiles, /import \{ useFileGone as \w+ \} from "\.\.\/files-changes\/file-gone-check\.mjs";/);
  assert.match(linkedFiles, /import \{ CurrentSessionIdContext as \w+ \} from "\.\.\/files-changes\/session-context\.mjs";/);
  assert.match(linkedFiles, /import \{[^}]*\bPa as \w+[^}]*\} from "\.\.\/routines-shared\/shared-0-DDOOdL6P\.mjs";/);
  // One copy of shared-130 WV (w9-low-transcript-rows-WV): code-current slices it; zH (its only reader here) is imported
  // from there, and session-rail's re-exports (saved-output WV, plugin-connector Ro) are recognised as links.
  const rows130 = fs.readFileSync(path.join(dir, 'shared-130.mjs'), 'utf8');
  assert.doesNotMatch(rows130, /^function (?:WV|zH)\(/m);
  assert.match(linkedFiles, /import \{ isClaudeConfigPath as \w+ \} from "\.\.\/code-current\/file-output-paths\.mjs";/);
  assert.match(linkedFiles, /import \{ parsePluginConnector as \w+ \} from "\.\.\/session-rail\/plugin-connector\.mjs";/);
  assert.ok(!manifest.modules.some(m => m.source === 'shared-130-dWztbTO1.js' && m.bindings.some(b => b.name === 'WV' || b.name === 'zH')), 'WV / zH: one copy (code-current)');
  assert.ok(fs.existsSync(path.join(app, 'scripts/verify-gen-transcript-rows.mjs')));
  const group = fs.readFileSync(path.join(dir, 'group-status.mjs'), 'utf8');
  assert.match(group, /import \{ TurnStatus as gf \} from "\.\.\/working-line\/turn-status\.mjs";/);
  for (const feature of ['_ = g ? "blocked" : h ? "busy" : i,', 'O = c && !x ? T : null,', 'VCe as GroupStatusRow', 'HCe as RunningToolRow'])
    assert.ok(group.includes(feature), feature);
  const mark = fs.readFileSync(path.join(dir, 'turn-mark.mjs'), 'utf8');
  assert.match(mark, /from "\.\.\/working-line\/morph\.mjs";/, 'the broker context is the working line\'s');
  assert.ok(mark.includes('"data-turn-mark-outlet": "",'));
  // No binding is sliced in both areas.
  const wl = JSON.parse(fs.readFileSync(path.join(app, 'src/generated/working-line/manifest.json'), 'utf8'));
  const held = new Set(wl.modules.flatMap(m => m.bindings.map(b => `${m.source}#${b.name}`)));
  for (const m of manifest.modules) for (const b of m.bindings) assert.ok(!held.has(`${m.source}#${b.name}`), `${m.source}#${b.name}`);
  // Review fix (w6-transcript-rows-cont), a wave 7 prerequisite: every import from a linked area names a semantic export
  // or one of that module's linkExports (its own 3.6556.2 local), never an E34 legacy name, so removing the legacy shims
  // (legacyExports, legacy segments) leaves this area resolving.
  const linkedManifests = Object.fromEntries(['working-line', 'session-rail', 'r3b-transcript', 'files-changes', 'code-current']
    .map(area => [area, JSON.parse(fs.readFileSync(path.join(app, 'src/generated', area, 'manifest.json'), 'utf8'))]));
  let linkedImports = 0;
  for (const m of manifest.modules) for (const imp of m.imports) {
    const hit = /^\.\.\/(working-line|session-rail|r3b-transcript|files-changes|code-current)\/(.+)$/.exec(imp.from);
    if (!hit) continue;
    linkedImports++;
    const owner = linkedManifests[hit[1]].modules.find(x => x.target === hit[2]);
    assert.ok(owner && !owner.legacyShim, imp.from);
    // code-current's modules carry no export table: the name must be one the file itself exports.
    const exportBlock = () => fs.readFileSync(path.join(app, 'src/generated', hit[1], hit[2]), 'utf8').split(/^export \{/m).at(-1);
    const ok = owner.exports ? Object.values(owner.exports).includes(imp.name) || (owner.linkExports ?? []).includes(imp.name)
      : exportBlock().split(/[\s,{}]+/).some((word, i, words) => word === imp.name && (words[i - 1] === 'as' || words[i + 1] !== 'as'));
    assert.ok(ok, `${m.target} imports ${imp.from} ${imp.name}: neither a semantic export nor a linkExports binding`);
    const legacy = owner.legacyExports?.[imp.name];
    assert.ok(!legacy || legacy === `${owner.source}#${imp.name}`, `${m.target} imports ${imp.from} ${imp.name}, an E34 legacy name`);
  }
  assert.ok(linkedImports >= 40, 'linked imports found');
});

