test('model: SDK tool names for the mark\'s activity, the live scope, the running candidate', () => {
  assert.deepEqual(Model.sdkToolOf({ type: 'commandExecution', command: 'ls' }), { name: 'Bash', input: { command: 'ls' } });
  assert.equal(Model.sdkToolOf({ type: 'agentMessage' }), null);
  const items = [{ id: 'a', turnId: 't', type: 'commandExecution', status: 'inProgress' }, { id: 'b', turnId: 't', type: 'agentMessage' }];
  const scope = Model.transcriptLiveScope({ sessionKey: 's', turnId: 't', items, responding: true, turnStats: { turnId: 't', startedAt: 10 }, awaiting: true });
  assert.deepEqual([...scope.liveRunningToolIds], ['a']);
  assert.equal(scope.turnStartedAt, 10000); assert.equal(scope.awaiting, true); assert.equal(scope.lastTool.name, 'Bash');
  assert.deepEqual(Model.runningCandidate(items[0]), { key: 'a', name: 'Bash', input: { command: '' }, wireRunning: true, toolIds: ['a'], runningIds: ['a'] });
  assert.equal(Model.stepState('unknown'), 'done');
});

// cb6930dae mo (`lastTool: c ?? s`, a "thinking" item resetting both): the mark's activity input while the turn responds.
test('model: the live scope\'s last tool follows mo: a thought forgets earlier tools, a running tool wins', () => {
  const tool = (id, command, status = 'completed') => ({ id, turnId: 't', type: 'commandExecution', command, status });
  const last = items => Model.transcriptLiveScope({ sessionKey: 's', turnId: 't', items, responding: true }).lastTool;
  assert.equal(last([tool('a', 'ls'), { id: 'r', turnId: 't', type: 'reasoning' }]), null, 'thinking after a tool: think');
  assert.equal(last([{ id: 'r', turnId: 't', type: 'reasoning' }, tool('a', 'ls')])?.input.command, 'ls');
  assert.equal(last([tool('a', 'npm test', 'inProgress'), tool('b', 'ls')])?.input.command, 'npm test', 'the running tool over the last one');
  assert.equal(last([tool('a', 'ls'), tool('b', 'pwd')])?.input.command, 'pwd');
  assert.equal(last([tool('x', 'ls'), { id: 'o', turnId: 'other', type: 'reasoning' }])?.input.command, 'ls', 'only the turn\'s own items');
  assert.equal(Model.transcriptLiveScope({ sessionKey: 's', turnId: 't', items: [tool('a', 'ls')], responding: false }).lastTool, null);
});

// The tool rows themselves (user ruling: the transcript follows the desktop): c96d752d0 n0 (v2e) / e0 / Uz (JIe) / HZ over
// the SDK tool calls the host converts its engine items to (transcript-sdk-tools.mjs), mounted by
// source-transcript-tool-rows.jsx; the host's bodies, cards and file opener through the adapters.
const strip = html => html.replace(/ class="[^"]*"/g, '');
const cmd = { id: 'c1', turnId: 't', type: 'commandExecution', command: 'npm test', description: 'Run the tests', status: 'completed', aggregatedOutput: 'PASS', exitCode: 0 };
const edit = { id: 'f1', turnId: 't', type: 'fileChange', status: 'completed', changes: [{ path: '/w/src/a.js', kind: { type: 'update' }, diff: '@@ -1,2 +1,3 @@\n a\n-b\n+c\n+d\n' }] };
const read = { id: 'r1', turnId: 't', type: 'commandExecution', command: 'cat a.js', status: 'completed', aggregatedOutput: '1\tconst a = 1', commandActions: [{ type: 'read', path: '/w/src/a.js', name: 'a.js' }] };

test('generator: the tool rows are originals, their boundary is pinned adapters', () => {
  const group = fs.readFileSync(path.join(dir, 'group-status.mjs'), 'utf8');
  // 3.6556.2 names (2.42304.0 n0 / e0 / Uz / HZ, JIe / v2e / UIe).
  for (const feature of ['i1 as ToolGroupRows', 'n1 as ToolGroupMember', 'iL as ToolRow', 'gX as ThoughtProcessStep', 'function BOe(', 'function Z1e(', 'function FOe(',
    '(e) => e.epitaxyEngineToolRow,', 'defaultMessage: "Needs your input",'])
    assert.ok(group.includes(feature), feature);
  const summary = fs.readFileSync(path.join(dir, 'rows-c52b02f3f-BejopSz8.mjs'), 'utf8');
  for (const feature of ['case "Bash":', 'defaultMessage: "Ran",', 'defaultMessage: "Searched web",', 'defaultMessage: "Ran agent",']) assert.ok(summary.includes(feature), feature);
  const c96 = manifest.modules.find(m => m.target === 'group-status.mjs');
  const adapted = new Set(c96.imports.filter(i => i.kind === 'adapter').map(i => i.name));
  for (const name of ['useEngineSurface', 'McpAppToolCard', 'PeerSendCard', 'CoordinatorMessageCard', 'EnvironmentSetupSteps', 'LiveOutputButton'])
    assert.ok(adapted.has(name), name);
  // w10-trans-proposal-inline (L30): mQ is TurnProposalGroup (proposal-group's copy through the adapter), no longer a null
  // "InlineSideSessions"; the pane context PZ (exported Rt) is this area's, exported for the host's provider.
  assert.deepEqual(c96.imports.filter(i => i.original === 'mQ').map(i => [i.local, i.name, i.kind]), [['mQ', 'TurnProposalGroupRow', 'adapter']]);
  assert.ok(!adapted.has('InlineSideSessions'));
  assert.equal(c96.exports.PZ, 'ProposalPaneContext');
  assert.ok(group.includes('var PZ = N({ inline: !1, captureGuardedSnapToBottom: zZe });'));
  const adapterText = fs.readFileSync(path.join(app, 'src/source-transcript-rows-adapters.jsx'), 'utf8');
  assert.match(adapterText, /^import \{ TurnProposalGroup \} from "\.\/generated\/proposal-group\/index\.mjs";$/m);
  assert.match(adapterText, /^export const TurnProposalGroupRow = TurnProposalGroup;$/m);
  assert.doesNotMatch(adapterText, /InlineSideSessions/);
  // L94: the Next renderer feed Aat (2.42304.0 nat) mounts its rows under c26fb8b6b's turnStatusRows provider forced on
  // (pinned through looseFeature, resolved to the minified match).
  const aat = manifest.callSites.find(site => site.binding === 'Aat');
  assert.equal(aat.source, 'c96d752d0-CWv_7-n9.js');
  assert.deepEqual(aat.features, ['defaultMessage: "Chat messages",', 'defaultMessage: "Currently streaming message",',
    'defaultMessage: "Use the up and down arrow keys to move between messages.",', 'f(Jm.Provider,{value:An,children:f(Nv,{value:!0,children:Pn})})']);
  // 2026-10-18: the result body (KIe → GIe → cb6930dae Tu) and the file link (c856385e2 In) are originals now.
  for (const name of ['HostToolResult', 'FileLink']) assert.ok(!adapted.has(name), name);
  // No local adapter shadows a declaration that is also sliced.
  const sliced = new Set(c96.bindings.map(b => b.name));
  for (const local of ['OE', 'PE', 'ME', 'jZ', 'OQ', 'OH', 'lY']) assert.ok(!sliced.has(local), local);
  for (const local of ['ROe', 'LOe', 'eL']) assert.ok(sliced.has(local), local);
  // TR-T6: the Agent row's "· {toolCallCount}" is its own shrink-0 span, so the count is never truncated.
  assert.match(group, /className: "text-body text-secondary shrink-0",\s*children: \[" ", "\\u00B7 ", Ce\.toolCallCount\]/, 'TR-T6');
});

